SELECT CONSTRUCTORS.URL FROM CONSTRUCTORS INNER JOIN (SELECT CONSTRUCTORID, SUM(WINS) AS TOTAL_WINS FROM CONSTRUCTORSTANDINGS GROUP BY CONSTRUCTORID ORDER BY TOTAL_WINS DESC LIMIT 1) AS TOP_CONSTRUCTOR ON CONSTRUCTORS.CONSTRUCTORID = TOP_CONSTRUCTOR.CONSTRUCTORID;
