-- ----------sql1------------
-- 2147483648, 2
SELECT DISTRICT.A2, COUNT(CLIENT.CLIENT_ID) AS FEMALE_ACCOUNT_HOLDERS FROM CLIENT INNER JOIN DISP ON CLIENT.CLIENT_ID = DISP.CLIENT_ID INNER JOIN DISTRICT ON CLIENT.DISTRICT_ID = DISTRICT.DISTRICT_ID WHERE CLIENT.GENDER = 'F' GROUP BY DISTRICT.DISTRICT_ID ORDER BY FEMALE_ACCOUNT_HOLDERS DESC LIMIT 9;
-- ----------sql2------------
-- 2147483648, 3
SELECT T2.A2, COUNT(T1.CLIENT_ID) FROM CLIENT AS T1 INNER JOIN DISTRICT AS T2 ON T1.DISTRICT_ID = T2.DISTRICT_ID WHERE T1.GENDER = 'F' GROUP BY T2.DISTRICT_ID, T2.A2 ORDER BY COUNT(T1.CLIENT_ID) DESC LIMIT 9;

