SELECT MAX(PITSTOPS.DURATION) FROM PITSTOPS INNER JOIN DRIVERS ON PITSTOPS.DRIVERID = DRIVERS.DRIVERID WHERE DRIVERS.FORENAME = 'LEWIS' AND DRIVERS.SURNAME = 'HAMILTON';
-- ----------sql2------------
